// 中学受験 国語（小学生向け・小4）の単元に、動く図解スライドを1つずつ。
// 「なぜ？」の連鎖で7枚以上。1枚ごとに全面を描きなおし、下の帯にそのスライドのひとこと。
import type { DiagramElement, DiagramFigure } from './figures';
import { C, FILL, bx, lb, ar, ln, ci, flow, show, fresh } from './diagram-kit';

type K = 'blue' | 'green' | 'red' | 'main' | 'purple' | 'gray';
const COL: Record<K, [string, string]> = {
  blue: [C.blue, FILL.blue], green: [C.green, FILL.green], red: [C.red, FILL.red],
  main: [C.main, FILL.warm], purple: [C.purple, FILL.purple], gray: [C.gray, FILL.gray],
};
const B = (x: number, y: number, w: number, h: number, t: string, k: K = 'main', size = 12) => bx(x, y, w, h, t, COL[k][0], COL[k][1], size);
const T = (t: string, y = 14, size = 12, color: string = C.ink) => lb(160, y, t, size, color, 'middle', true);
const cap = (t: string, color: string = C.ink, size = 12) => lb(160, 192, t, size, color, 'middle', true);
const cap2 = (t1: string, t2: string, k: K = 'main'): DiagramElement[] => [lb(160, 166, t1, 11, C.gray, 'middle'), B(20, 178, 280, 44, t2, k, 13)];
const big = (x: number, y: number, t: string, color: string = C.ink, size = 38) => lb(x, y, t, size, color, 'middle', true);
const cols = (items: [string, K][], y: number, h: number, size = 12, pad = 10, gap = 8) => {
  const n = items.length; const w = (320 - pad * 2 - gap * (n - 1)) / n;
  return items.map(([t, k], i) => B(pad + i * (w + gap), y, w, h, t, k, size));
};
const rows = (items: [string, K][], y0: number, h: number, gap = 6, size = 12, x = 10, w = 300) =>
  items.map(([t, k], i) => B(x, y0 + i * (h + gap), w, h, t, k, size));
/** 左の箱 → 右の箱 を縦にならべる */
const pairs = (items: [string, string, K][], y0: number, h: number, gap = 6, lw = 120, size = 12, x = 10, w = 300) =>
  items.flatMap(([l, r, k], i) => {
    const y = y0 + i * (h + gap);
    return [B(x, y, lw, h, l, k, size), ar(x + lw + 2, y + h / 2, x + lw + 22, y + h / 2, COL[k][0]), B(x + lw + 24, y, w - lw - 24, h, r, k, size)];
  });
const chain = (labels: string[], y: number, h: number, k: K = 'blue', size = 12) =>
  flow(labels, y, { h, color: COL[k][0], fill: COL[k][1], size }).flat();
const FF = (note: string, ...els: (DiagramElement | DiagramElement[])[]) => ({ note, add: fresh(...els.flat()) });

